SELECT ?point ?label WHERE {
  ?point a brick:Chiller .
  OPTIONAL { ?point rdfs:label ?label . }
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?point ?class ?label WHERE {
  OPTIONAL { ?point brick:hasPrimaryTag ?tag . }
  ?point rdfs:label ?label .
  OPTIONAL { ?point ?class ?o . FILTER(isIRI(?class)) . }
  FILTER(?label = "Chiller01" || lcase(str(?label)) = "chiller01") .
}

